parameters.jsonBody:
{
  "dry_run": false,
  "max_records": 40,
  "send_email": true,
  "send_whatsapp": true,
  "include_invoice_whatsapp": true,
  "template_language": "en",
  "views": [
    {
      "view_name": "Auto Send Invoice & Pickup",
      "default_location": "Hurghada/Cairo",
      "max_records": 40
    }
  ],
  "templates": {
    "pickup": {
      "default": "whatsapp_pickup_time",
      "Sharm": "pickup_time_new1"
    },
    "flight": {
      "default": "attachment_pickup"
    },
    "extra_ticket": {
      "default": "fts_ticket"
    },
    "qr": {
      "default": "new_qr_ticket"
    },
    "qr_with_pickup": {
      "default": "qr_tickets_with_pickup"
    },
    "audio_guide": {
      "default": "audio_guide_app"
    },
    "payment": {
      "default": "ftstravels_confirm_payment"
    }
  }
}
